import sys

def solve():
    input = sys.stdin.read
    data = input().split()
    iterator = iter(data)

    t = int(next(iterator))
    results = []

    for _ in range(t):
        n = int(next(iterator))
        m = int(next(iterator))

        grid = []
        for _ in range(n):
            row = [int(next(iterator)) for _ in range(m)]
            grid.append(row)

        # Find columns that violate the non-decreasing condition
        bad_cols = []
        for j in range(1, m):
            for i in range(n):
                if grid[i][j] < grid[i][j-1]:
                    bad_cols.append(j)
                    break

        if not bad_cols:
            results.append("1 1")
            continue

        # If more than 2 bad columns, it's impossible to fix with one swap
        if len(bad_cols) > 2:
            results.append("-1")
            continue

        # Candidates for swapping: the bad columns and their left neighbors
        candidates = set()
        for j in bad_cols:
            candidates.add(j)
            if j > 0:
                candidates.add(j - 1)

        # Try swapping each pair of candidates
        candidate_list = sorted(list(candidates))
        found = False

        for i_idx in range(len(candidate_list)):
            for j_idx in range(i_idx, len(candidate_list)):
                c1 = candidate_list[i_idx]
                c2 = candidate_list[j_idx]

                # Check if swapping c1 and c2 makes the grid good
                valid = True
                for r in range(n):
                    # Create a temporary view of the row with swapped columns
                    row_vals = grid[r][:]
                    row_vals[c1], row_vals[c2] = row_vals[c2], row_vals[c1]

                    for k in range(1, m):
                        if row_vals[k] < row_vals[k-1]:
                            valid = False
                            break
                    if not valid:
                        break

                if valid:
                    results.append(f"{c1 + 1} {c2 + 1}")
                    found = True
                    break
            if found:
                break

        if not found:
            results.append("-1")

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
